  {
    "title": "Next Quarter Focus",
    "bullets": [
      "Prioritize inclusive design in all new projects",
      "Launch a streamlined onboarding process for new clients",
      "Explore partnerships with local community organizations for social impact work"
    ],
    "notes": "This quarter will build on our strengths while expanding our reach and purpose. Inclusive design and community engagement align with both client demand and our values.",
    "layout": "title-content"
  }
]}
